// Merge the persisted customer record back into the normalized envelope.
// Envelope fields are restored from the workflow trigger (they are replaced by
// the Postgres node output inside this sub-workflow).
const envelope = $('When Called by Another Workflow').first().json;
const row = $input.first().json;

let metadata = row.metadata;
if (typeof metadata === 'string') {
  try { metadata = JSON.parse(metadata); } catch (e) { metadata = {}; }
}

const customer = {
  id: row.id,
  external_id: row.external_id,
  name: row.name,
  email: row.email,
  channel: row.channel,
  first_interaction_at: row.first_interaction_at,
  last_interaction_at: row.last_interaction_at,
  metadata
};

return [{ json: { ...envelope, customer } }];
